import {emptyProject,makeTrack} from '../../web-studio/model.js';import {newSynth} from '../../web-studio/instruments.js';
export function sessionBatchProject(){const p=emptyProject();p.name='Session Clipboard QA';p.tracks=[{...makeTrack('Folder',0),id:'g',group:true},{...makeTrack('Lead',1),id:'a',parentId:'g',instrument:newSynth('Init')},{...makeTrack('Bass',2),id:'b',parentId:'g',instrument:newSynth('Init')}];for(const [id,name,pitch] of [['x','Shared Loop',60],['y','Lead Variation',64],['z','Bass Loop',48]])p.clips[id]={id,name,kind:'midi',sourceBpm:120,beats:4,notes:[{pitch,start:0,duration:3.5,velocity:.5}]};p.tracks[1].slots=['x','y',null,null];p.tracks[2].slots=['z',null,'x',null];p.arrangement=[{id:'reference',trackId:'a',clipId:'x',start:0,length:4,offset:0}];p.transport.launchQuantization=0;return p;}
